import React from "react";
import { ChevronDown, ArrowRight } from "lucide-react";
import JewelArt from "./JewelArt";
import { COLORS, FONT_DISPLAY } from "../constants/theme";

export default function Hero({ scrollTo }) {
  return (
    <section id="top" style={{ position: "relative", minHeight: "100vh", background: COLORS.ink, color: COLORS.bone, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(ellipse at 75% 30%, ${COLORS.verdigris}55, transparent 55%), radial-gradient(ellipse at 15% 80%, ${COLORS.rust}40, transparent 50%)`,
        }}
      />
      <div
        className="spin-slow"
        style={{ position: "absolute", right: "-8%", top: "10%", width: "60vw", maxWidth: 640, opacity: 0.5, color: COLORS.gold }}
      >
        <JewelArt type="ring" />
      </div>

      <div style={{ position: "relative", maxWidth: 1240, margin: "0 auto" }} className="px-6 md:px-10">
        <div style={{ minHeight: "100vh", display: "flex", flexDirection: "column", justifyContent: "center", paddingTop: 90 }}>
          <p style={{ fontSize: 13, letterSpacing: "0.22em", textTransform: "uppercase", color: COLORS.gold, marginBottom: 22 }}>
            Fine jewelry, cast from reclaimed metal
          </p>
          <h1
            style={{
              fontFamily: FONT_DISPLAY,
              fontWeight: 400,
              fontSize: "clamp(40px, 7vw, 92px)",
              lineHeight: 1.02,
              maxWidth: 820,
              letterSpacing: "-0.01em",
            }}
          >
            Jewelry cast from{" "}
            <span style={{ fontStyle: "italic", fontWeight: 400 }}>what the earth</span> remembers.
          </h1>
          <p style={{ marginTop: 26, fontSize: 17, lineHeight: 1.6, maxWidth: 480, color: "rgba(236,229,216,0.78)" }}>
            Every piece begins as reclaimed gold and silver — old rings, coin scrap,
            a grandmother's chain — melted down and carved into something new.
            Nothing mined for this collection. Nothing rushed.
          </p>
          <div className="flex flex-wrap items-center" style={{ gap: 18, marginTop: 40 }}>
            <button
              onClick={() => scrollTo("shop")}
              style={{
                background: COLORS.gold,
                color: COLORS.ink,
                border: "none",
                padding: "16px 30px",
                fontSize: 14,
                letterSpacing: "0.04em",
                display: "inline-flex",
                alignItems: "center",
                gap: 10,
              }}
            >
              Shop the collection <ArrowRight size={16} />
            </button>
            <button
              onClick={() => scrollTo("craft")}
              className="underline-grow"
              style={{ background: "none", border: "none", color: COLORS.bone, fontSize: 14, letterSpacing: "0.04em" }}
            >
              Read our story
            </button>
          </div>
        </div>
      </div>

      <button
        onClick={() => scrollTo("marquee")}
        aria-label="Scroll down"
        style={{
          position: "absolute",
          bottom: 28,
          left: "50%",
          transform: "translateX(-50%)",
          background: "none",
          border: "none",
          color: COLORS.bone,
          opacity: 0.7,
        }}
      >
        <ChevronDown size={22} />
      </button>
    </section>
  );
}
